import { Router } from 'express';
import * as webhookCtrl from '../controllers/webhook.controller.js';
import { authenticate, requireRole, validate } from '../middleware/index.js';
import { createWebhookSchema, updateWebhookSchema } from '../validators/index.js';
const router = Router();
router.use(authenticate, requireRole('admin'));
router.get('/', webhookCtrl.listWebhooksController);
router.post('/', validate({ body: createWebhookSchema }), webhookCtrl.createWebhookController);
router.get('/:id', webhookCtrl.getWebhookController);
router.put('/:id', validate({ body: updateWebhookSchema }), webhookCtrl.updateWebhookController);
router.delete('/:id', webhookCtrl.deleteWebhookController);
router.get('/:id/deliveries', webhookCtrl.webhookDeliveriesController);
export default router;
